Here is a JavaScript function that flattens a nested array using recursion.

```javascript
/**
 * Flattens a nested array into a single-level array.
 *
 * @param {Array<any>} arr The nested array to flatten.
 * @returns {Array<any>} A new, one-dimensional array containing all elements.
 */
function flattenArray(arr) {
  let flattened = [];

  for (const element of arr) {
    if (Array.isArray(element)) {
      // If the element is an array, recursively flatten it and concatenate the result
      flattened = flattened.concat(flattenArray(element));
    } else {
      // If the element is not an array, push it directly
      flattened.push(element);
    }
  }

  return flattened;
}

