/**
 * Groups an array of objects by a specified property.
 *
 * @param {Array<Object>} arr The array of objects to group.
 * @param {string} key The property name by which to group the objects.
 * @returns {Object<string, Array<Object>>} An object where keys are the unique values
 *          of the grouping property, and values are arrays of objects belonging to that group.
 */
function groupBy(arr, key) {
  if (!Array.isArray(arr)) {
    throw new Error("The first argument must be an array.");
  }
  if (typeof key !== 'string' || key.length === 0) {
    throw new Error("The second argument must be a non-empty string representing the property key.");
  }

  return arr.reduce((accumulator, currentObject) => {
    // Get the value of the grouping key for the current object
    const groupKey = currentObject[key];

    // If the accumulator doesn't have this group key yet, initialize it with an empty array
    if (!accumulator[groupKey]) {
      accumulator[groupKey] = [];
    }

    // Push the current object into the appropriate group array
    accumulator[groupKey].push(currentObject);

    // Return the updated accumulator for the next iteration
    return accumulator;
  }, {}); // Initialize the accumulator as an empty object
}

