/**
 * Removes duplicate elements from an array, returning a new array with only unique values.
 *
 * @param arr The input array which may contain duplicate elements.
 * @returns A new array containing only the unique elements from the input array.
 */
function removeDuplicates<T>(arr: T[]): T[] {
  // A Set automatically stores only unique values.
  // We create a new Set from the array, and then convert it back into an array
  // using the spread operator (...).
  return [...new Set(arr)];
}

