This solution uses the `reduce` method for an efficient and functional approach.

```typescript
/**
 * Defines the structure for the objects in the input array.
 * You can adjust this interface based on the actual structure of your data.
 */
interface DataItem {
  id: number;
  category: string;
  value: number;
}

/**
 * Groups an array of objects by the value of a specified key.
 *
 * @param arr The array of objects to group.
 * @param key The key in the objects to group by.
 * @returns A Map where keys are the unique values of the grouping key, and values are arrays of objects belonging to that group.
 */
function groupBy<T extends Record<string, any>, K extends keyof T>(
  arr: T[],
  key: K
): Map<T[K], T[]> {
  return arr.reduce((acc: Map<T[K], T[]>, currentItem: T): Map<T[K], T[]> => {
    // Get the value of the grouping key for the current item
    const groupKey: T[K] = currentItem[key];

    // Check if the accumulator already has an array for this key
    if (!acc.has(groupKey)) {
      // If not, initialize a new array for this key
      acc.set(groupKey, []);
    }

    // Get the existing array and push the current item into it
    const groupArray: T[] = acc.get(groupKey)!;
    groupArray.push(currentItem);

    // Return the updated accumulator
    return acc;
  }, new Map<T[K], T[]>());
}

