Here is a TypeScript function that checks whether the parentheses in a string are balanced. This implementation handles three types of parentheses: `()`, `[]`, and `{}`.

```typescript
/**
 * Checks if the parentheses in a given string are balanced.
 *
 * It iterates through the string, using a stack to keep track of opening parentheses.
 * It ensures that:
 * 1. Every opening parenthesis has a corresponding closing one.
 * 2. Parentheses are closed in the correct order (e.g., `([{}])` is valid, `([)]` is not).
 *
 * @param str The input string to check.
 * @returns True if the parentheses are balanced, false otherwise.
 */
function areParenthesesBalanced(str: string): boolean {
    const stack: string[] = [];
    const map: { [key: string]: string } = {
        ')': '(',
        ']': '[',
        '}': '{'
    };

    for (const char of str) {
        // 1. If the character is an opening bracket, push it onto the stack.
        if (['(', '[', '{'].includes(char)) {
            stack.push(char);
        } 
        // 2. If the character is a closing bracket.
        else if (Object.keys(map).includes(char)) {
            // If the stack is empty, we have a closing bracket without a corresponding opener.
            if (stack.length === 0) {
                return false;
            }

            // Pop the last opened bracket and check if it matches the current closing bracket.
            const lastOpen = stack.pop();
            if (lastOpen !== map[char]) {
                return false; // Mismatched types (e.g., opening '(' but closing ']')
            }
        }
        // Ignore all other characters (letters, numbers, spaces, etc.)
    }

    // 3. After iterating through the whole string, the stack must be empty for the string to be balanced.
    return stack.length === 0;
}

// --- Examples ---

console.log(`"([]{})": ${areParenthesesBalanced("([]{})")}`); // true
console.log(`"([{}])": ${areParenthesesBalanced("([{}])")}`); // true
console.log(`"((()))": ${areParenthesesBalanced("((()))")}`); // true
console.log(`"([)]": ${areParenthesesBalanced("([)]")}`);     // false (Mismatched order)
console.log(`"(((": ${areParenthesesBalanced("(((")}`);       // false (Unclosed opening brackets)
console.log(`"]": ${areParenthesesBalanced("]")}`);           // false (Closing bracket first)
console.log(`"": ${areParenthesesBalanced("")}`);             // true (Empty string is balanced)
console.log(`"a + (b * [c])": ${areParenthesesBalanced("a + (b * [c])")}`); // true (Ignores non-bracket characters)
console.log(`"{[()]}}": ${areParenthesesBalanced("{[()]}}")}`); // false (Extra closing brace)
