```typescript
/**
 * Calculates the sum of all numeric values in an object.
 *
 * @param obj The object to sum values from. The values must be numbers.
 * @returns The total sum of the numeric values in the object. Returns 0 if the object is null, undefined, or has no numeric properties.
 */
function sumObjectValues<T extends Record<string, number>>(obj: T): number {
  if (!obj) {
    return 0;
  }

  let sum: number = 0;

  // Iterate over the keys of the object
  for (const key in obj) {
    // Ensure the property belongs to the object itself (good practice)
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      const value = obj[key];
      // Check if the value is a finite number before adding it to the sum
      if (typeof value === 'number' && isFinite(value)) {
        sum += value;
      }
    }
  }

  return sum;
}

