Here is a C function that copies a string without using `strcpy`. This implementation manually iterates through the source string and copies each character to the destination buffer, ensuring null termination.

```c
#include <stdio.h>
#include <string.h>

/**
 * @brief Copies a string from a source buffer to a destination buffer without using strcpy.
 *
 * This function iterates through the source string character by character
 * and copies them to the destination buffer until the null terminator is reached.
 *
 * @param destination The buffer where the string will be copied.
 * @param source The string to be copied from.
 * @return int Returns 0 on success, or -1 if the destination buffer is too small
 *             to hold the entire source string (including the null terminator).
 */
int custom_strncpy(char *destination, const char *source) {
    if (destination == NULL || source == NULL) {
        return -1; // Handle null pointers
    }

    int i = 0;
    // Iterate through the source string until the null terminator is found
    while (source[i] != '\0') {
        destination[i] = source[i];
        i++;
    }

    // Crucially, manually add the null terminator to the destination string
    destination[i] = '\0';

    return 0; // Success
}

int main() {
    char source[] = "Hello, World!";
    // Allocate a buffer large enough for the source string plus the null terminator
    char destination[100];

    printf("Source string: \"%s\"\n", source);

    if (custom_strncpy(destination, source) == 0) {
        printf("Copy successful.\n");
        printf("Destination string: \"%s\"\n", destination);
    } else {
        printf("Copy failed (buffer too small or error).\n");
    }

    // Test case 2: Empty string
    char source2[] = "";
    char destination2[10];
    if (custom_strncpy(destination2, source2) == 0) {
        printf("\nCopy of empty string successful.\n");
        printf("Destination string: \"%s\"\n", destination2);
    }

    // Test case 3: Buffer overflow check (if we try to copy a very long string)
    char long_source[200];
    memset(long_source, 'A', 199);
    long_source[199] = '\0';

    char small_dest[50];
    printf("\nTesting buffer overflow scenario...\n");
    if (custom_strncpy(small_dest, long_source) != 0) {
        printf("Copy correctly failed due to buffer size limitation.\n");
    }

    return 0;
}
```

