Here is a Rust function that removes duplicates from a `Vec<T>`.

The most idiomatic way to do this is by using a `HashSet` to keep track of the elements encountered so far, and then collecting the unique elements back into a `Vec`.

```rust
use std::collections::HashSet;

/// Removes duplicate elements from a vector, preserving the order of first appearance.
///
/// # Arguments
///
/// * `vec` - The input vector containing elements that may include duplicates.
///
/// # Returns
///
/// A new `Vec<T>` containing only the unique elements from the input vector.
///
/// # Examples
///
/// ```
/// let numbers = vec![1, 2, 2, 3, 4, 4, 5];
/// let unique_numbers = remove_duplicates(&numbers);
/// assert_eq!(unique_numbers, vec![1, 2, 3, 4, 5]);
///
/// let strings = vec!["apple", "banana", "apple", "cherry"];
/// let unique_strings = remove_duplicates(&strings);
/// assert_eq!(unique_strings, vec!["apple", "banana", "cherry"]);
/// ```
pub fn remove_duplicates<T: Eq + std::hash::Hash + Clone>(vec: &Vec<T>) -> Vec<T> {
    let mut seen: HashSet<T> = HashSet::new();
    let mut result: Vec<T> = Vec::new();

    for item in vec {
        // insert returns true if the value was not already present
        if seen.insert(item.clone()) {
            result.push(item.clone());
        }
    }

    result
}

fn main() {
    // Example 1: Integers
    let numbers = vec![1, 2, 2, 3, 4, 4, 5, 1];
    let unique_numbers = remove_duplicates(&numbers);
    println!("Original numbers: {:?}", numbers);
    println!("Unique numbers: {:?}", unique_numbers);
    // Expected output: [1, 2, 3, 4, 5]

    println!("--------------------");

    // Example 2: Strings
    let strings = vec!["apple", "banana", "apple", "cherry", "banana"];
    let unique_strings = remove_duplicates(&strings);
    println!("Original strings: {:?}", strings);
    println!("Unique strings: {:?}", unique_strings);
    // Expected output: ["apple", "banana", "cherry"]
}
```

